import java.io.PrintWriter;
import java.io.BufferedOutputStream;
import java.util.Arrays;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (ptr >= len) {
                ptr = 0;
                try {
                    len = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public long nextLong() {
            int c = readByte();
            while (c <= ' ' && c != -1) {
                c = readByte();
            }
            if (c == -1) return -1;
            long val = 0;
            while (c > ' ') {
                if (c >= '0' && c <= '9') {
                    val = val * 10 + (c - '0');
                }
                c = readByte();
            }
            return val;
        }

        public int nextInt() {
            return (int) nextLong();
        }
    }

    static class Edge implements Comparable<Edge> {
        int u, v;
        long w;

        Edge(int u, int v, long w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }

        @Override
        public int compareTo(Edge o) {
            return Long.compare(this.w, o.w);
        }
    }

    static class DSU {
        int[] parent;

        DSU(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int find(int i) {
            if (parent[i] == i)
                return i;
            return parent[i] = find(parent[i]);
        }

        void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                parent[rootI] = rootJ;
            }
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        int n = sc.nextInt();
        if (n <= 0) return;
        int m = sc.nextInt();

        int totalCells = n * m;
        long[] P = new long[totalCells];

        for (int i = 0; i < totalCells; i++) {
            P[i] = sc.nextLong();
        }

        int edgeCount = 0;
        int maxEdges = (n > 1 ? (n - 1) * m : 0) + (m > 1 ? n * (m - 1) : 0);
        Edge[] edges = new Edge[maxEdges];

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                int u = r * m + c;
                if (r + 1 < n) {
                    int v = (r + 1) * m + c;
                    edges[edgeCount++] = new Edge(u, v, Math.max(P[u], P[v]));
                }
                if (c + 1 < m) {
                    int v = r * m + (c + 1);
                    edges[edgeCount++] = new Edge(u, v, Math.max(P[u], P[v]));
                }
            }
        }

        Arrays.sort(edges);

        int maxNodes = 2 * totalCells;
        long[] S = new long[maxNodes];
        long[] weight = new long[maxNodes];
        int[] leftChild = new int[maxNodes];
        int[] rightChild = new int[maxNodes];
        long[] ans = new long[maxNodes];

        Arrays.fill(leftChild, -1);
        Arrays.fill(rightChild, -1);

        for (int i = 0; i < totalCells; i++) {
            S[i] = P[i];
        }

        DSU dsu = new DSU(maxNodes);
        int currNode = totalCells;

        for (int i = 0; i < edgeCount; i++) {
            Edge e = edges[i];
            int rootU = dsu.find(e.u);
            int rootV = dsu.find(e.v);
            if (rootU != rootV) {
                int newNode = currNode++;
                weight[newNode] = e.w;
                S[newNode] = S[rootU] + S[rootV];
                leftChild[newNode] = rootU;
                rightChild[newNode] = rootV;

                dsu.parent[rootU] = newNode;
                dsu.parent[rootV] = newNode;
            }
        }

        int root = currNode - 1;
        ans[root] = S[root];

        for (int i = root; i >= totalCells; i--) {
            int l = leftChild[i];
            int r = rightChild[i];

            if (l != -1) {
                if (S[l] >= weight[i]) {
                    ans[l] = ans[i];
                } else {
                    ans[l] = S[l];
                }
            }

            if (r != -1) {
                if (S[r] >= weight[i]) {
                    ans[r] = ans[i];
                } else {
                    ans[r] = S[r];
                }
            }
        }

        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        StringBuilder sb = new StringBuilder();

        for (int r = 0; r < n; r++) {
            sb.setLength(0);
            for (int c = 0; c < m; c++) {
                int idx = r * m + c;
                if (c > 0) sb.append(' ');
                sb.append(ans[idx]);
            }
            out.println(sb.toString());
        }

        out.flush();
    }
}
